const src = $json.body || $json || {};
const runId = src.run_id || src.runId || null;
const caseId = src.case_id || src.caseId || null;
if (!runId && !caseId) throw new Error('run_id or case_id is required for CRIS QA cleanup');
const dryRun = src.dry_run !== false && String(src.dry_run || 'true').toLowerCase() !== 'false';
const restoreSnapshot = src.restore_snapshot === true || String(src.restore_snapshot || '').toLowerCase() === 'true';
return [{ json: { run_id: runId, case_id: caseId, dry_run: dryRun, restore_snapshot: restoreSnapshot, requested_by: src.requested_by || 'n8n-cris-qa' } }];
